<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use App\Models\{Product,Location,Stock,Movement};
class InventoryTest extends TestCase {
 use RefreshDatabase;
 private function fixture():array {return [Product::create(['sku'=>'TEST-01','name'=>'Teclado','category'=>'Periféricos','minimum'=>5,'cost'=>10]),Location::create(['name'=>'Bodega']),Location::create(['name'=>'Oficina'])];}
 private function movement($p,$a,$b,$type='traslado',$quantity=3):array{return ['product_id'=>$p->id,'type'=>$type,'from_id'=>$a->id,'to_id'=>$b->id,'quantity'=>$quantity,'occurred_at'=>now()->subMinute()->format('Y-m-d H:i:s'),'responsible'=>'Prueba'];}
 public function test_transfer_preserves_total_and_history():void {[$p,$a,$b]=$this->fixture();Stock::create(['product_id'=>$p->id,'location_id'=>$a->id,'quantity'=>10]);$this->post('/movements',$this->movement($p,$a,$b))->assertSessionHasNoErrors();$this->assertDatabaseHas('stocks',['location_id'=>$a->id,'quantity'=>7]);$this->assertDatabaseHas('stocks',['location_id'=>$b->id,'quantity'=>3]);$this->assertDatabaseHas('movements',['from_id'=>$a->id,'to_id'=>$b->id,'quantity'=>3]);$this->assertEquals(10,Stock::sum('quantity'));}
 public function test_insufficient_stock_rolls_back_everything():void {[$p,$a,$b]=$this->fixture();Stock::create(['product_id'=>$p->id,'location_id'=>$a->id,'quantity'=>2]);$this->post('/movements',$this->movement($p,$a,$b))->assertSessionHasErrors('quantity');$this->assertEquals(2,Stock::sum('quantity'));$this->assertDatabaseCount('movements',0);$this->assertDatabaseCount('stocks',1);}
 public function test_rejects_same_location_zero_and_future_date():void {[$p,$a,$b]=$this->fixture();$this->post('/movements',$this->movement($p,$a,$a))->assertSessionHasErrors('movement');$this->post('/movements',$this->movement($p,$a,$b,'entrada',0))->assertSessionHasErrors('quantity');$d=$this->movement($p,$a,$b,'entrada');$d['occurred_at']=now()->addDay()->format('Y-m-d H:i:s');$this->post('/movements',$d)->assertSessionHasErrors('occurred_at');$this->assertDatabaseCount('movements',0);}
 public function test_entry_exit_and_soft_delete_preserve_history():void {[$p,$a,$b]=$this->fixture();$this->post('/movements',$this->movement($p,$a,$b,'entrada',5))->assertSessionHasNoErrors();$this->delete('/products/'.$p->id)->assertSessionHasErrors('product');$this->post('/movements',$this->movement($p,$b,$a,'salida',5))->assertSessionHasNoErrors();$this->delete('/products/'.$p->id)->assertSessionHasNoErrors();$this->assertSoftDeleted($p);$this->assertDatabaseCount('movements',2);$this->get('/movements')->assertOk()->assertSee('Teclado');$this->post('/movements',$this->movement($p,$a,$b,'entrada'))->assertSessionHasErrors('product_id');}
 public function test_crud_audit_unique_sku_and_location_integrity():void {[$p,$a,$b]=$this->fixture();$data=['sku'=>'NEW','name'=>'Mouse','category'=>'Periféricos','minimum'=>3,'cost'=>100];$this->post('/products',$data)->assertSessionHasNoErrors();$this->post('/products',$data)->assertSessionHasErrors('sku');$this->put('/products/'.$p->id,[...$data,'sku'=>$p->sku])->assertSessionHasNoErrors();$this->assertDatabaseHas('audits',['action'=>'Producto editado']);$this->post('/locations',['name'=>'Laboratorio'])->assertSessionHasNoErrors();$this->put('/locations/'.$b->id,['name'=>'Oficina 2'])->assertSessionHasNoErrors();$this->post('/movements',$this->movement($p,$a,$b,'entrada'))->assertSessionHasNoErrors();$this->delete('/locations/'.$b->id)->assertSessionHasErrors('location');}
 public function test_pages_filters_and_exports():void {[$p,$a,$b]=$this->fixture();$this->post('/movements',$this->movement($p,$a,$b,'entrada'))->assertSessionHasNoErrors();foreach(['/','/products','/movements','/locations','/reports','/audit','/products?q=Teclado','/products?low=1'] as $url)$this->get($url)->assertOk();$this->get('/movements?type=salida')->assertDontSee('Prueba');$this->get('/export/json?dataset=movements')->assertOk()->assertJsonCount(1,'records');$this->get('/export/json?dataset=movements&start=2099-01-01')->assertJsonCount(0,'records');foreach(['inventory','movements'] as $set){$this->get('/export/pdf?dataset='.$set)->assertOk()->assertHeader('content-type','application/pdf');$xlsx=$this->get('/export/xlsx?dataset='.$set);$xlsx->assertOk();$this->assertStringStartsWith('PK',$xlsx->streamedContent());$csv=$this->get('/export/csv?dataset='.$set);$csv->assertOk();$this->assertStringContainsString('Teclado',$csv->streamedContent());}}
}
